int i[] = primpoints(0, @primnum);

setpointgroup(0, "pin", i[0], 1);
setpointgroup(0, "pin", i[len(i)-1], 1);

float r= rand(@primnum);

vector p0 = point(0, "P", i[0]);
vector p1 = point(0, "P", i[len(i)-1]);

setpointattrib(0, "dir", i[len(i)-1], normalize(p0-p1));
setpointattrib(0, "dir", i[0], normalize(p1-p0));

vector com = point(1, "P", 0);
f@density = chramp("d", 0.1*length(v@P-com));
f@pscale = 1.0-f@density;
